B.b1C=new A.bs("prophets","Stories of the Prophets","Peace be upon them all")
B.b1X=new A.bs("women","Women of Islam","The hearts that carried the light")
B.b1l=new A.bs("seerah","The Seerah","The life of the Prophet \u0635\u0644\u0649 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647 \u0648\u0633\u0644\u0645")
